module barrel_shifter (
    input [7:0] in,
    input [2:0] ctrl,
    output reg [7:0] out
);

reg [7:0] temp;

always @(*) begin
    temp = in;
    if (ctrl[2]) begin
        temp = {temp[3:0], temp[7:4]};
    end
    if (ctrl[1]) begin
        temp = {temp[1:0], temp[7:2]};
    end
    if (ctrl[0]) begin
        temp = {temp[0], temp[7:1]};
    end
    out = temp;
end

endmodule

module mux2X1( in0,in1,sel,out);
input in0,in1;
input sel;
output out;
assign out=(sel)?in1:in0;
endmodule
